/**
 * Initial mount — creates DOM nodes for every GraphNode and
 * attaches them into the container.
 *
 * This is a recursive depth-first walk. For each GraphNode:
 *  1. Create the DOM element (or text node)
 *  2. Apply props/attributes
 *  3. Wire events
 *  4. Wire signal subscriptions for reactive props
 *  5. Recurse into children
 *  6. Insert into the DOM
 */

import type { GraphNode, ApplicationGraph } from '@streetui/graph';
import type { DOMAdapter } from '@streetui/dom';
import {
  focusInitial,
  trapFocus,
  containFocus,
  onEscape,
  rovingMenu,
  saveFocus,
  restoreFocus,
} from '@streetui/dom';
import type { RenderContext } from './render-context.js';
import { NodeInstance } from './node-instance.js';
import { applyProp } from './attributes.js';
import { wireEvents } from './events.js';
import { resolveTag } from './tag-map.js';
import {
  reconcileChildren,
  reconcileChildrenByPlan,
  type PlanEntry,
} from './reconciliation.js';
import { TransitionController, type TransitionHooks } from './transition.js';
import { wireHeadBehavior } from './head.js';

/**
 * Prop keys handled by the per-type mount branches (or reserved internals), so
 * `applyNodeProps` must skip them to avoid double-applying. This set is
 * invariant across nodes, so it is hoisted to module scope: allocating it once
 * (rather than per node) removes N Set allocations per mount/SSR pass and the
 * GC pressure they create. Treat as read-only — never mutate.
 */
const SKIP_PROP_KEYS: ReadonlySet<string> = new Set([
  'text', 'label', 'level', 'inputType', 'src', 'alt', 'href', 'external',
  'value', 'placeholder', 'disabled', '_renderKey', 'key', 'name',
]);

export function mountGraph(ctx: RenderContext): NodeInstance {
  return mountNode(ctx, ctx.graph.root, ctx.container);
}

export function mountNode(
  ctx: RenderContext,
  graphNode: GraphNode,
  parentDom: Node,
): NodeInstance {
  const { dom, graph } = ctx;

  // ── v1.7 static SSR fast path (SSR-only) ──────────────────────────────────
  // When a compiler-derived static SSR plan is present (server render only)
  // and this node is a maximal static-subtree root, emit its precomputed HTML
  // verbatim instead of recursively constructing ServerElement/ServerText/
  // NodeInstance for the whole subtree. `ctx.staticHTML` is always undefined on
  // the browser path, so this is a single short-circuiting check there — the
  // client hot path and its semantics are untouched (§5/§6/§23). The stored
  // string is produced by this same mount+serialize pipeline, so output is
  // byte-identical (§8). We still register ONE NodeInstance for the root so the
  // parent's children bookkeeping and post-render dispose behave normally.
  const staticHTML = ctx.staticHTML;
  if (staticHTML !== undefined && dom.createRawHTML !== undefined) {
    const precomputed = staticHTML.get(graphNode.id);
    if (precomputed !== undefined) {
      const raw = dom.createRawHTML(precomputed);
      dom.appendChild(parentDom, raw);
      const instance = new NodeInstance(graphNode, raw);
      ctx.instances.set(graphNode.id, instance);
      return instance;
    }
  }

  // The application root node maps to the container itself — don't create a duplicate element
  if (graphNode.type === 'application') {
    const instance = new NodeInstance(graphNode, parentDom);
    ctx.instances.set(graphNode.id, instance);
    for (const child of graphNode.children) {
      const childInstance = mountNode(ctx, child, parentDom);
      instance.addChild(childInstance);
    }
    return instance;
  }

  // Text-only nodes render as a <span> containing a text node
  if (graphNode.type === 'text') {
    const text = String(graphNode.getProp('text') ?? '');
    const el = dom.createElement('span');
    const textNode = dom.createTextNode(text);
    dom.appendChild(el, textNode);
    applyNodeProps(ctx, graphNode, el);

    // Create the live instance up front and reuse it for event wiring. The
    // previous code allocated a throwaway NodeInstance solely to satisfy
    // wireEvents' signature, wasting one NodeInstance (+ its children array and
    // CleanupRegistry) per text node — pure GC pressure on the hottest mount
    // path. wireEvents/wireSignalBindings each early-return on empty arrays.
    const instance = new NodeInstance(graphNode, el);
    ctx.instances.set(graphNode.id, instance);
    wireEvents(dom, graph, graphNode, el, instance);

    // Reactive text binding — only build the update closure when the node has
    // bindings. wireSignalBindings early-returns on empty stateRefs, so for a
    // static text node (the common case in a large initial render) the
    // textUpdate closure would be allocated and thrown away: avoidable GC
    // pressure on the hottest mount path.
    if (graphNode.stateRefs.length !== 0) {
      wireSignalBindings(ctx, graphNode, instance, textUpdate(dom, el, textNode));
    }

    dom.appendChild(parentDom, el);
    return instance;
  }

  // Heading nodes
  if (graphNode.type === 'heading') {
    const level = (graphNode.getProp('level') as number | undefined) ?? 1;
    const tag = `h${level}` as string;
    const el = dom.createElement(tag);
    const text = String(graphNode.getProp('text') ?? '');
    dom.setTextContent(el, text);
    applyNodeProps(ctx, graphNode, el);

    const instance = new NodeInstance(graphNode, el);
    ctx.instances.set(graphNode.id, instance);
    wireEvents(dom, graph, graphNode, el, instance);

    if (graphNode.stateRefs.length !== 0) {
      wireSignalBindings(ctx, graphNode, instance, headingUpdate(dom, el));
    }

    dom.appendChild(parentDom, el);
    return instance;
  }

  // Input nodes
  if (graphNode.type === 'input') {
    const el = dom.createElement('input') as HTMLInputElement;
    const inputType = String(graphNode.getProp('inputType') ?? 'text');
    dom.setAttribute(el, 'type', inputType);
    const placeholder = graphNode.getProp('placeholder');
    if (placeholder !== undefined) dom.setAttribute(el, 'placeholder', String(placeholder));
    const value = graphNode.getProp('value');
    if (value !== undefined) dom.setProperty(el, 'value', String(value));
    applyNodeProps(ctx, graphNode, el);

    const instance = new NodeInstance(graphNode, el);
    ctx.instances.set(graphNode.id, instance);
    wireEvents(dom, graph, graphNode, el, instance);

    if (graphNode.stateRefs.length !== 0) {
      wireSignalBindings(ctx, graphNode, instance, inputUpdate(dom, el));
    }

    dom.appendChild(parentDom, el);
    return instance;
  }

  // Image nodes
  if (graphNode.type === 'image') {
    const el = dom.createElement('img') as HTMLImageElement;
    const src = graphNode.getProp('src');
    const alt = graphNode.getProp('alt');
    if (src !== undefined) dom.setAttribute(el, 'src', String(src));
    if (alt !== undefined) dom.setAttribute(el, 'alt', String(alt));
    const width = graphNode.getProp('width');
    const height = graphNode.getProp('height');
    if (width !== undefined) dom.setAttribute(el, 'width', String(width));
    if (height !== undefined) dom.setAttribute(el, 'height', String(height));
    applyNodeProps(ctx, graphNode, el);

    const instance = new NodeInstance(graphNode, el);
    ctx.instances.set(graphNode.id, instance);
    dom.appendChild(parentDom, el);
    return instance;
  }

  // Link nodes
  if (graphNode.type === 'link') {
    const el = dom.createElement('a') as HTMLAnchorElement;
    const href = graphNode.getProp('href');
    const label = graphNode.getProp('label');
    const external = graphNode.getProp('external');
    if (href !== undefined) dom.setAttribute(el, 'href', String(href));
    if (label !== undefined) dom.setTextContent(el, String(label));
    if (external === true) {
      dom.setAttribute(el, 'target', '_blank');
      dom.setAttribute(el, 'rel', 'noopener noreferrer');
    }
    applyNodeProps(ctx, graphNode, el);

    const instance = new NodeInstance(graphNode, el);
    ctx.instances.set(graphNode.id, instance);
    wireEvents(dom, graph, graphNode, el, instance);

    // A link's label/href may be bound to signals (e.g. i18n `t()` in nav). Wire
    // the same signal-binding path buttons use so the text updates reactively.
    if (graphNode.stateRefs.length !== 0) {
      wireSignalBindings(ctx, graphNode, instance, linkUpdate(dom, el));
    }

    dom.appendChild(parentDom, el);
    return instance;
  }

  // Button nodes
  if (graphNode.type === 'button') {
    const el = dom.createElement('button') as HTMLButtonElement;
    const label = graphNode.getProp('label');
    if (label !== undefined) dom.setTextContent(el, String(label));
    const disabled = graphNode.getProp('disabled');
    if (disabled === true) dom.setAttribute(el, 'disabled', '');
    applyNodeProps(ctx, graphNode, el);

    const instance = new NodeInstance(graphNode, el);
    ctx.instances.set(graphNode.id, instance);
    wireEvents(dom, graph, graphNode, el, instance);

    if (graphNode.stateRefs.length !== 0) {
      wireSignalBindings(ctx, graphNode, instance, buttonUpdate(dom, el));
    }

    dom.appendChild(parentDom, el);
    return instance;
  }

  // Reactive list / conditional — a container whose children are driven by a
  // Signal. Initial child subtrees are already built into the graph by the DSL;
  // on signal change we reconcile the freshly-built desired children against the
  // live DOM using the keyed reconciler (no virtual DOM). A `conditional` uses
  // the identical machinery but renders as a neutral <div> holding 0..1 branch.
  if (graphNode.type === 'reactive-list' || graphNode.type === 'conditional') {
    const tag = resolveTag(graphNode.type);
    const el = dom.createElement(tag);
    applyNodeProps(ctx, graphNode, el);

    const instance = new NodeInstance(graphNode, el);
    ctx.instances.set(graphNode.id, instance);

    for (const child of graphNode.children) {
      const childInstance = mountNode(ctx, child, el);
      instance.addChild(childInstance);
    }

    dom.appendChild(parentDom, el);
    wireReactiveList(ctx, graphNode, instance, el, true);
    return instance;
  }

  // Portal — a container whose children are relocated to a different DOM
  // location (document.body) on the browser, while a neutral inline anchor
  // stays at the declaration site. On the server there is no body, so the
  // children render inline in the anchor (deterministic HTML; hydration then
  // relocates them). This is the substrate for overlays (dialog/popover/…):
  // `wireOverlayBehavior` reads an optional `__overlay__<id>` descriptor and,
  // when present, wires focus trap/restore/containment/escape to the open
  // signal. A plain portal has no descriptor, so overlay wiring is a no-op.
  if (graphNode.type === 'portal') {
    const anchor = dom.createElement(resolveTag('portal'));
    dom.setAttribute(anchor, 'data-streetui-portal', '');
    applyNodeProps(ctx, graphNode, anchor);
    const instance = new NodeInstance(graphNode, anchor);
    ctx.instances.set(graphNode.id, instance);

    const body = dom.body();
    let target: Element = anchor; // SSR / no body → render inline in the anchor
    if (body !== null) {
      const portalContainer = dom.createElement('div');
      dom.setAttribute(portalContainer, 'data-streetui-portal-container', '');
      dom.appendChild(body, portalContainer);
      instance.trackCleanup(() => dom.removeChild(body, portalContainer));
      target = portalContainer;
    }

    for (const child of graphNode.children) {
      instance.addChild(mountNode(ctx, child, target));
    }

    dom.appendChild(parentDom, anchor);
    wireOverlayBehavior(ctx, graphNode, instance, target);
    return instance;
  }

  // Head — a metadata node (title/meta/link/base). Renders as a neutral inline
  // anchor at the declaration site (like a portal), while its contribution is
  // applied to `document.head` by `wireHeadBehavior` (browser) or emitted by
  // `renderHead` (server). No visible children; the anchor keeps hydration
  // structurally aligned with the SSR output.
  if (graphNode.type === 'head') {
    const anchor = dom.createElement(resolveTag('head'));
    dom.setAttribute(anchor, 'data-streetui-head-anchor', '');
    applyNodeProps(ctx, graphNode, anchor);
    const instance = new NodeInstance(graphNode, anchor);
    ctx.instances.set(graphNode.id, instance);

    dom.appendChild(parentDom, anchor);
    wireHeadBehavior(ctx, graphNode, instance);
    return instance;
  }

  // Container / section / page / form / list / list-item — structural nodes
  const tag = resolveTag(graphNode.type);
  const el = dom.createElement(tag);
  applyNodeProps(ctx, graphNode, el);

  // Surface a reactive-list item's stable, identity-only reconciliation key as a
  // public `data-streetui-key` attribute (e.g. "id:1"). This exposes only the
  // identity part — never the internal `_sig` value signature, signal ids or
  // graph node ids — so a row is directly selectable and its identity is
  // inspectable across reorders and in-place data updates.
  if (graphNode.type === 'list-item') {
    const itemKey = graphNode.getProp('key');
    if (itemKey !== undefined) {
      dom.setAttribute(el, 'data-streetui-key', String(itemKey));
    }
  }

  const instance = new NodeInstance(graphNode, el);
  ctx.instances.set(graphNode.id, instance);

  // wire form submit (reuse the live instance rather than a throwaway)
  if (graphNode.type === 'form') {
    wireEvents(dom, graph, graphNode, el, instance);
  }

  // Recurse into children
  for (const child of graphNode.children) {
    const childInstance = mountNode(ctx, child, el);
    instance.addChild(childInstance);
  }

  dom.appendChild(parentDom, el);
  if (graphNode.type === 'component') wireComponentBehavior(ctx, graphNode, instance);
  return instance;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Per-node-type reactive-binding factories. Each returns the `onUpdate`
 * callback that `wireSignalBindings` invokes when a bound signal changes.
 * Extracted so both the browser mount path and the hydration path apply the
 * exact same DOM mutation semantics for each prop — no duplicated rendering
 * logic.
 */
export function textUpdate(
  dom: DOMAdapter,
  el: Element,
  textNode: Text,
): (propKey: string, value: unknown) => void {
  return (propKey, value) => {
    if (propKey === 'text') {
      dom.setTextContent(textNode, String(value ?? ''));
    } else {
      applyProp(dom, el, propKey, value);
    }
  };
}

export function headingUpdate(
  dom: DOMAdapter,
  el: Element,
): (propKey: string, value: unknown) => void {
  return (propKey, value) => {
    if (propKey === 'text') {
      dom.setTextContent(el, String(value ?? ''));
    } else {
      applyProp(dom, el, propKey, value);
    }
  };
}

export function inputUpdate(
  dom: DOMAdapter,
  el: Element,
): (propKey: string, value: unknown) => void {
  return (propKey, value) => {
    if (propKey === 'value') {
      dom.setProperty(el, 'value', String(value ?? ''));
    } else {
      applyProp(dom, el, propKey, value);
    }
  };
}

export function buttonUpdate(
  dom: DOMAdapter,
  el: Element,
): (propKey: string, value: unknown) => void {
  return (propKey, value) => {
    if (propKey === 'label') {
      dom.setTextContent(el, String(value ?? ''));
    } else if (propKey === 'disabled') {
      if (value === true) {
        dom.setAttribute(el, 'disabled', '');
      } else {
        dom.removeAttribute(el, 'disabled');
      }
    } else {
      applyProp(dom, el, propKey, value);
    }
  };
}

export function linkUpdate(
  dom: DOMAdapter,
  el: Element,
): (propKey: string, value: unknown) => void {
  return (propKey, value) => {
    if (propKey === 'label') {
      dom.setTextContent(el, String(value ?? ''));
    } else if (propKey === 'href') {
      dom.setAttribute(el, 'href', String(value ?? ''));
    } else {
      applyProp(dom, el, propKey, value);
    }
  };
}

export function applyNodeProps(ctx: RenderContext, graphNode: GraphNode, el: Element): void {
  // Iterate own enumerable keys directly rather than via Object.entries, which
  // allocates a wrapper array plus one [key,value] tuple per prop — measurable
  // GC pressure when multiplied across every node in a large initial render.
  const props = graphNode.props;
  for (const key in props) {
    if (!Object.hasOwn(props, key)) continue;
    if (SKIP_PROP_KEYS.has(key)) continue;
    applyProp(ctx.dom, el, key, props[key]);
  }
}

export function wireSignalBindings(
  ctx: RenderContext,
  graphNode: GraphNode,
  instance: NodeInstance,
  onUpdate: (propKey: string, value: unknown) => void,
): void {
  // Fast exit for the common non-reactive node — avoids allocating a for-of
  // iterator over an empty stateRefs array on every static node.
  if (graphNode.stateRefs.length === 0) return;
  for (const stateRef of graphNode.stateRefs) {
    const signalKey = `__signal__${stateRef.signalId}`;
    const maybeSig = ctx.graph.getHandler(signalKey) as
      | { subscribe: (fn: (v: unknown) => void) => () => void; peek: () => unknown }
      | undefined;
    if (maybeSig === undefined || typeof maybeSig.subscribe !== 'function') continue;

    // Subscribe directly — avoids the ReadonlySignal<T> generic variance issue
    const unsub = maybeSig.subscribe((value) => {
      onUpdate(stateRef.propKey, value);
    });
    instance.trackCleanup(unsub);
  }
}

// ── Reactive list wiring ────────────────────────────────────────────────────────

type ListBuildFn = (items: unknown) => GraphNode[];
type ListPlanFn = (items: unknown) => PlanEntry[];

/**
 * Subscribe a reactive-list instance to its driving signal. On each change the
 * DSL-registered plan factory produces lightweight per-row descriptors, which
 * are reconciled against the live DOM with the keyed, minimal-move reconciler
 * (spec §15). A `conditional` node has no plan handler and falls back to the
 * eager build factory (it only ever renders 0..1 branch, so eager is fine).
 */
export function wireReactiveList(
  ctx: RenderContext,
  graphNode: GraphNode,
  instance: NodeInstance,
  el: Element,
  runAppear = false,
): void {
  const plan = ctx.graph.getHandler(`__listplan__${graphNode.id}`) as
    | ListPlanFn
    | undefined;
  const build = ctx.graph.getHandler(`__listbuild__${graphNode.id}`) as
    | ListBuildFn
    | undefined;
  if (plan === undefined && build === undefined) return;

  // One transition controller per reactive container, created here so its
  // leaving-instance map survives across every reconcile of this container
  // (that persistence is what makes leave→enter reclaim and keyed list-leave
  // correct — §6/§7). `finalize` runs the full deferred teardown chain when a
  // leave animation completes: DOM-remove + dispose + forget + detach, exactly
  // the work the synchronous path splits between the reconciler and the two
  // reconcile* helpers below. On the server (no body) the controller's hooks
  // no-op, so SSR is unchanged (§21).
  const controller = new TransitionController(ctx.dom, ctx.graph, (leaving) => {
    // Full teardown at leave-animation end — the same four steps the synchronous
    // path splits between the reconciler (DOM-remove + dispose) and this helper
    // (forget + detach). Deferred here because `beginLeave` excluded this
    // instance from `result.removed`, so nothing else will tear it down.
    const parent = ctx.dom.parentNode(leaving.domNode);
    if (parent !== null) ctx.dom.removeChild(parent, leaving.domNode);
    leaving.dispose();
    forgetInstance(ctx, leaving);
    ctx.graph.detachNode(leaving.graphNode);
  });
  const hooks = controller.hooks();

  // `appear`: animate any initial child that opted in — but ONLY on a fresh
  // browser mount, never on hydration (§22: the DOM is already present and
  // correct, so appear must not run). The hydrate path calls this with
  // `runAppear` omitted (false).
  if (runAppear) controller.appear(instance.children);

  for (const stateRef of graphNode.stateRefs) {
    if (stateRef.propKey !== 'items') continue;
    const sig = ctx.graph.getHandler(`__signal__${stateRef.signalId}`) as
      | { subscribe: (fn: (v: unknown) => void) => () => void }
      | undefined;
    if (sig === undefined || typeof sig.subscribe !== 'function') continue;

    const unsub = sig.subscribe((value) => {
      if (plan !== undefined) {
        reconcileReactiveListByPlan(ctx, graphNode, instance, el, plan(value), hooks);
      } else {
        reconcileReactiveList(ctx, graphNode, instance, el, build!(value), hooks);
      }
    });
    instance.trackCleanup(unsub);
  }
}

function reconcileReactiveListByPlan(
  ctx: RenderContext,
  listNode: GraphNode,
  listInstance: NodeInstance,
  listEl: Element,
  plan: PlanEntry[],
  hooks: TransitionHooks,
): void {
  const oldInstances = [...listInstance.children];
  const result = reconcileChildrenByPlan(
    ctx,
    listEl,
    oldInstances,
    plan,
    (node, parent) => mountNode(ctx, node, parent),
    hooks,
  );

  // Sync the live instance's children to the reconciled order.
  listInstance.children.length = 0;
  for (const inst of result.instances) listInstance.children.push(inst);

  // Forget removed instances, and drop their graph nodes.
  for (const removed of result.removed) {
    forgetInstance(ctx, removed);
    ctx.graph.detachNode(removed.graphNode);
  }
  // Detach any freshly-built subtree that was not adopted as a live instance
  // (e.g. the top node of a rebuilt changed row, whose live instance keeps its
  // original graph node).
  const adopted = new Set(result.instances.map((i) => i.graphNode));
  for (const node of result.built ?? []) {
    if (!adopted.has(node)) ctx.graph.detachNode(node);
  }

  // Keep the graph model consistent: list node children match the new order.
  for (const child of [...listNode.children]) listNode.removeChild(child);
  for (const inst of result.instances) listNode.appendChild(inst.graphNode);
}

function reconcileReactiveList(
  ctx: RenderContext,
  listNode: GraphNode,
  listInstance: NodeInstance,
  listEl: Element,
  newNodes: GraphNode[],
  hooks: TransitionHooks,
): void {
  const oldInstances = [...listInstance.children];
  const result = reconcileChildren(
    ctx,
    listEl,
    oldInstances,
    newNodes,
    (node, parent) => mountNode(ctx, node, parent),
    hooks,
  );

  // Sync the live instance's children to the reconciled order.
  listInstance.children.length = 0;
  for (const inst of result.instances) listInstance.children.push(inst);

  // Forget removed instances from the renderer index, and drop their graph
  // nodes (and any un-adopted freshly-built duplicates) from the graph index.
  for (const removed of result.removed) {
    forgetInstance(ctx, removed);
    ctx.graph.detachNode(removed.graphNode);
  }
  const adopted = new Set(result.instances.map((i) => i.graphNode));
  for (const built of newNodes) {
    if (!adopted.has(built)) ctx.graph.detachNode(built);
  }

  // Keep the graph model consistent: list node children match the new order.
  for (const child of [...listNode.children]) listNode.removeChild(child);
  for (const inst of result.instances) listNode.appendChild(inst.graphNode);
}

/** Recursively remove an instance subtree from the renderer's instance index. */
function forgetInstance(ctx: RenderContext, instance: NodeInstance): void {
  ctx.instances.delete(instance.graphNode.id);
  for (const child of instance.children) forgetInstance(ctx, child);
}

// ── Overlay behavior wiring ─────────────────────────────────────────────────────

/**
 * Opaque overlay descriptor, read from the `__overlay__<portalId>` handler that
 * the DSL registers for dialog/popover/tooltip/dropdown/toast. Declared here as
 * a local structural type (mirroring the list plan/build handler pattern) so the
 * renderer never takes a compile-time dependency on the DSL package.
 */
interface OverlayBehavior {
  /** Reactive open/visibility state — the same signal that drives the panel's `when()`. */
  readonly open: {
    subscribe: (fn: (v: boolean) => void) => () => void;
    peek: () => unknown;
  };
  /** Trap Tab focus within, and redirect escaped focus back inside (modal semantics). */
  readonly modal: boolean;
  /** Move focus into the panel when it opens. */
  readonly takesFocus: boolean;
  /** Wire arrow/Home/End/Enter/Space roving-focus navigation (role="menu"). */
  readonly menu: boolean;
  /** Escape key invokes `onClose`. */
  readonly closeOnEscape: boolean;
  /** Restore focus to the pre-open element on close. */
  readonly restoreFocus: boolean;
  /** id of the element to focus first when opening. */
  readonly initialFocusId?: string;
  /** Requested-close callback (Escape). The app flips its own open signal here. */
  readonly onClose?: () => void;
}

/**
 * Attach overlay focus/keyboard behavior to a mounted portal. Server-safe: on
 * the server `dom.body()` is null so this returns immediately (SSR emits inert
 * markup, no focus concept). A plain portal has no `__overlay__` descriptor, so
 * this also returns immediately — the behavior is purely additive.
 *
 * The panel is mounted/unmounted by the portal's inner `when(open, …)`, whose
 * signal subscription is registered *before* this one (the conditional child is
 * mounted earlier in the portal branch). Signal subscribers fire synchronously
 * in subscription order, so on open→true the panel DOM exists before we move
 * focus into it, and on open→false the panel is torn down before we restore
 * focus. All listeners are tracked on the instance and torn down on unmount.
 */
export function wireOverlayBehavior(
  ctx: RenderContext,
  graphNode: GraphNode,
  instance: NodeInstance,
  target: Element,
): void {
  const { dom, graph } = ctx;
  if (dom.body() === null) return; // server / no DOM environment

  const descFn = graph.getHandler(`__overlay__${graphNode.id}`) as
    | (() => OverlayBehavior)
    | undefined;
  if (descFn === undefined) return; // plain portal — no overlay behavior

  const desc = descFn();
  const openSig = desc.open;
  if (openSig === undefined || typeof openSig.subscribe !== 'function') return;

  let active: Array<() => void> = [];
  let saved: Element | null = null;

  const teardown = (): void => {
    for (const fn of active) fn();
    active = [];
  };

  const onOpenChange = (isOpen: boolean): void => {
    if (isOpen) {
      if (desc.restoreFocus) saved = saveFocus(dom);
      // Establish containment/roving BEFORE moving focus in, so that when a
      // nested modal opens it becomes the authoritative focus owner before its
      // initial focus fires — otherwise the outer modal's still-active
      // containment would pull that focus back out (§16).
      if (desc.modal) {
        active.push(trapFocus(dom, target));
        active.push(containFocus(dom, target));
      }
      if (desc.menu) {
        active.push(rovingMenu(dom, target));
      }
      if (desc.takesFocus) focusInitial(dom, target, desc.initialFocusId);
      if (desc.closeOnEscape && desc.onClose !== undefined) {
        active.push(onEscape(dom, target, desc.onClose));
      }
    } else {
      teardown();
      if (desc.restoreFocus && saved !== null) {
        restoreFocus(dom, saved);
        saved = null;
      }
    }
  };

  const unsub = openSig.subscribe(onOpenChange);
  instance.trackCleanup(unsub);
  instance.trackCleanup(teardown);

  // `subscribe` fires only on change; an overlay that is open on initial mount
  // has its panel already built into the graph, so run the open path now.
  if (openSig.peek() === true) onOpenChange(true);
}

/**
 * Wire a component instance's lifecycle (§9). Reads the optional
 * `__component__<id>` descriptor — an array of teardown callbacks the DSL's
 * `component()` collected from the setup's `ctx.effect`/`ctx.onCleanup` — and
 * routes each into `NodeInstance.trackCleanup`, so they run (children-first)
 * when the component leaves the graph. Shared by the mount and hydrate paths so
 * both attach identical ownership. A `'component'` node with no cleanups (no
 * effects/resources) registers no descriptor and this is a no-op.
 */
export function wireComponentBehavior(
  ctx: RenderContext,
  graphNode: GraphNode,
  instance: NodeInstance,
): void {
  const fn = ctx.graph.getHandler(`__component__${graphNode.id}`) as
    | (() => Array<() => void>)
    | undefined;
  if (fn === undefined) return;
  for (const cleanup of fn()) instance.trackCleanup(cleanup);
}
